import {validateScenarioSpeed} from './scenario-speed.js?v=airport-flights-1';
import {validateScenarioArea,scenarioAreaLabel} from './scenario-area.js?v=airport-flights-1';
import {validateScenarioStory} from './scenario-story.js?v=airport-flights-1';
import {validateEventDefinitions,scenarioEventGoals} from './scenario-events.js?v=airport-flights-1';
import {CUSTOM_METRICS} from './scenario-metrics.js?v=airport-flights-1';
export {CUSTOM_METRICS} from './scenario-metrics.js?v=airport-flights-1';
export function validateCustomDefinition(v){if(!v||typeof v.title!=='string'||!v.title.trim()||v.title.length>60||/[\x00-\x1f]/.test(v.title)||!Number.isInteger(v.months)||v.months<12||v.months>1200||!Array.isArray(v.objectives)||v.objectives.length<1||v.objectives.length>4)throw Error('Choose a title, a 12–1200 month deadline, and one to four goals.');const eventMode=v.eventMode??'monthly';if(!['monthly','together'].includes(eventMode))throw Error('Choose one event per month or grouped actions.');const holdMonths=v.holdMonths??1;if(!Number.isInteger(holdMonths)||holdMonths<1||holdMonths>v.months)throw Error('Hold goals for 1 to the deadline’s number of months.');const seen=new Set();const objectives=v.objectives.map(o=>{const m=Object.hasOwn(CUSTOM_METRICS,o?.metric)?CUSTOM_METRICS[o.metric]:null;const area=validateScenarioArea(o.area,m),key=o.metric+JSON.stringify(area);if(!m||seen.has(key)||!Number.isFinite(o.target)||o.target<(m.min||0)||o.target>m.max||m.integer&&!Number.isInteger(o.target))throw Error('Choose distinct goals with targets inside their allowed ranges.');seen.add(key);return{metric:o.metric,target:o.target,...(area?{area}:{})};});return{eventMode,speed:validateScenarioSpeed(v.speed),...validateScenarioStory(v),title:v.title.trim(),months:v.months,holdMonths,objectives,events:validateEventDefinitions(v.events,v.months,eventMode)};}
export function customCurrentGoals(c){return [...scenarioEventGoals(c),...c.scenario.definition.objectives.map(o=>{const m=CUSTOM_METRICS[o.metric],value=m.read(c,o.area);return{...(o.area?{area:o.area}:{}),title:`${m.name}${scenarioAreaLabel(o.area)}: ${m.states?m.states[o.target]:m.direction+' '+o.target.toLocaleString()}`,done:m.direction==='equals'?value===o.target:m.direction==='at least'?value>=o.target:value<=o.target,detail:`Current: ${m.states?m.states[value]:value.toLocaleString(undefined,{maximumFractionDigits:1})}`};})];}
export function attachCustomScenario(c,definition){if(c.emergency.active)throw Error('Finish the active emergency before creating a challenge.');const d=validateCustomDefinition(definition);c.scenario={id:'custom',definition:d,events:d.events.map(()=>({status:'pending',month:null,runs:0})),status:'playing',startMonth:c.month,lastChecked:c.month,streak:0,eventFired:false,endedMonth:null,rank:null};return c.scenario;}

export function advanceCustomStreak(c){const s=c.scenario;s.streak=customCurrentGoals(c).every(g=>g.done)?Math.min(s.definition.holdMonths,s.streak+1):0;}
export function customGoals(c){const s=c.scenario,goals=customCurrentGoals(c);if(s.definition.holdMonths>1)goals.unshift({title:`Hold every goal for ${s.definition.holdMonths} consecutive months`,done:s.streak>=s.definition.holdMonths,detail:`${s.streak} / ${s.definition.holdMonths} months. Missing a goal resets progress; required events and emergency response must finish before the streak begins.`});return goals;}
